//! Parity and regression tests for the indextts family.
//!
//! Pinned fixtures reside in `testdata/tts_indextts/`, generated by
//! `tools/gen_indextts_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference modules (the indextts `Model` at
//! tiny seeded dims, the true `prepare_input_embedding` and generate
//! loop over a conditioned BigVGAN vocoder, and the true
//! `log_mel_spectrogram`), so the traces carry the reference mel,
//! conditioning, prompt embedding, greedy mel-code loop, and waveform.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::{GenerateParams, Model, ModelConfig, StopReason};

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_indextts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Filtered logit entries use null for the reference's negative
/// infinities (strict JSON cannot carry them).
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| {
            if v.is_null() {
                f32::NEG_INFINITY
            } else {
                v.as_f64().expect("value") as f32
            }
        })
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum differences against the fixture traces when the
/// gates were frozen; assertions use these values, not re-measured ones.
const MEL_TOLERANCE: f32 = 1e-4;
const CONDITIONING_TOLERANCE: f32 = 2e-5;
const LATENT_TOLERANCE: f32 = 2e-5;
const WAVEFORM_TOLERANCE: f32 = 2e-4;

fn fixture_model() -> Model {
    Model::open(&testdata("generate")).expect("family model loads")
}

#[test]
fn mel_matches_the_reference_rows() {
    let traces = read_json(&testdata("generate/traces.json"));
    let model = fixture_model();
    let samples = f32_vec(&traces["ref_audio"]);
    let mel = model.log_mel_spectrogram(&samples).expect("mel");
    let flat: Vec<f32> = mel.concat();
    let want = f32_vec(&traces["ref_mel"]);
    assert_eq!(mel.len(), traces["ref_mel_rows"].as_u64().unwrap() as usize);
    let diff = max_abs_diff(&flat, &want);
    assert!(diff <= MEL_TOLERANCE, "mel diff {diff}");
}

#[test]
fn conditioning_matches_the_reference_rows() {
    let traces = read_json(&testdata("generate/traces.json"));
    let model = fixture_model();
    let samples = f32_vec(&traces["ref_audio"]);
    let mel = model.log_mel_spectrogram(&samples).expect("mel");
    let rows: Vec<f32> = mel.concat();
    let conditioning = model
        .get_conditioning(&rows, mel.len())
        .expect("conditioning");
    let diff = max_abs_diff(&conditioning, &f32_vec(&traces["conditioning"]));
    assert!(diff <= CONDITIONING_TOLERANCE, "conditioning diff {diff}");
    assert_eq!(
        conditioning.len(),
        model.config.gpt.condition_num_latent * model.config.gpt.model_dim
    );
}

#[test]
fn prompt_embedding_matches_the_reference() {
    let traces = read_json(&testdata("generate/traces.json"));
    let model = fixture_model();
    let samples = f32_vec(&traces["ref_audio"]);
    let mel = model.log_mel_spectrogram(&samples).expect("mel");
    let rows: Vec<f32> = mel.concat();
    let conditioning = model
        .get_conditioning(&rows, mel.len())
        .expect("conditioning");
    let text_ids = i32_vec(&traces["text_ids"]);
    let (embedding, length) = model
        .prepare_input_embedding(&conditioning, &text_ids)
        .expect("prompt");
    assert_eq!(length, traces["prompt_length"].as_u64().unwrap() as usize);
    let diff = max_abs_diff(&embedding, &f32_vec(&traces["prompt_embedding"]));
    assert!(
        diff <= CONDITIONING_TOLERANCE,
        "prompt embedding diff {diff}"
    );
}

fn run_scenario(model: &mut Model, traces: &Value, index: usize) {
    let scenario = &traces["scenarios"][index];
    let samples = f32_vec(&traces["ref_audio"]);
    let mel = model.log_mel_spectrogram(&samples).expect("mel");
    let text_ids = i32_vec(&traces["text_ids"]);
    let params = GenerateParams {
        temperature: 0.0,
        top_p: None,
        top_k: None,
        max_tokens: scenario["max_tokens"].as_u64().unwrap() as usize,
    };
    let got = model
        .generate(&mel, &text_ids, &params, 0)
        .unwrap_or_else(|error| panic!("scenario {} generate failed: {error}", scenario["name"]));
    let want_stop = scenario["stop_reason"].as_str().expect("stop reason");
    if want_stop == "stop-mel-token" {
        assert_eq!(got.stopped_by, StopReason::StopMelToken);
    } else {
        assert_eq!(got.stopped_by, StopReason::MaxTokens, "want {want_stop}");
    }
    assert_eq!(
        got.tokens,
        i32_vec(&scenario["tokens"]),
        "scenario {} sampled ids differ",
        scenario["name"]
    );
    assert_eq!(
        got.latent_states.len(),
        scenario["num_latent_rows"].as_u64().unwrap() as usize * model.config.gpt.model_dim
    );
    let diff = max_abs_diff(&got.latent_states, &f32_vec(&scenario["latent_states"]));
    assert!(
        diff <= LATENT_TOLERANCE,
        "scenario {} latent diff {diff}",
        scenario["name"]
    );
    let diff = max_abs_diff(&got.samples, &f32_vec(&scenario["waveform"]));
    assert!(
        diff <= WAVEFORM_TOLERANCE,
        "scenario {} waveform diff {diff}",
        scenario["name"]
    );
}

#[test]
fn greedy_generation_stops_at_the_stop_token_with_reference_latents() {
    let traces = read_json(&testdata("generate/traces.json"));
    let mut model = fixture_model();
    run_scenario(&mut model, &traces, 0);
}

#[test]
fn greedy_generation_stops_at_max_tokens_with_reference_latents() {
    let traces = read_json(&testdata("generate/traces.json"));
    let mut model = fixture_model();
    run_scenario(&mut model, &traces, 1);
}

#[test]
fn sampler_matches_the_reference_on_fixed_logits() {
    let traces = read_json(&testdata("sampler/traces.json"));
    for case in traces["cases"].as_array().expect("cases") {
        let logits = f32_vec(&case["logits"]);
        let greedy = crate::tts::sampling::argmax(&logits);
        assert_eq!(
            greedy as i64,
            case["greedy"].as_i64().unwrap(),
            "case {} greedy",
            case["name"]
        );
        if let Some(masked) = case.get("top_k_masked") {
            let top_k = case["top_k"].as_u64().unwrap() as usize;
            let mut masked_logits = logits.clone();
            crate::tts::sampling::apply_top_k(&mut masked_logits, top_k).expect("filters");
            let diff = max_abs_diff(&masked_logits, &f32_vec_masked(masked));
            assert!(diff <= 1e-6, "case {} top_k mask diff {diff}", case["name"]);
        }
    }
}

#[test]
fn family_config_defaults_and_refusals_match_the_reference() {
    let fixture_config = read_json(&testdata("generate/config.json"));
    let config = ModelConfig::from_json(&fixture_config).expect("parses");
    assert_eq!(config.gpt.model_dim, 32);
    assert_eq!(config.gpt.number_mel_codes, 16);
    assert_eq!(config.gpt.start_mel_token, 14);
    assert_eq!(config.gpt.stop_mel_token, 15);
    assert_eq!(config.gpt.max_conditioning_inputs, 1);
    assert_eq!(config.gpt.condition_num_latent, 8);
    assert_eq!(config.sample_rate, 24000);
    assert_eq!(config.bigvgan.gpt_dim, 32);
    assert_eq!(config.bigvgan.speaker_embedding_dim, 4);
    assert!(config.bigvgan.cond_d_vector_in_each_upsampling_layer);

    let refused = ModelConfig::from_json(&serde_json::json!({
        "bigvgan": fixture_config["bigvgan"],
        "gpt": {
            "model_dim": 32, "heads": 4, "layers": 2,
            "max_mel_tokens": 48, "max_text_tokens": 48,
            "number_text_tokens": 24, "number_mel_codes": 16,
            "start_mel_token": 14, "stop_mel_token": 15,
            "start_text_token": 22, "stop_text_token": 23,
            "use_mel_codes_as_input": false,
            "mel_length_compression": 1024,
            "condition_type": "conformer_perceiver",
            "condition_module": fixture_config["gpt"]["condition_module"]
        }
    }))
    .unwrap_err();
    assert!(
        refused.to_string().contains("use_mel_codes_as_input"),
        "{refused}"
    );

    let refused = ModelConfig::from_json(&serde_json::json!({
        "bigvgan": fixture_config["bigvgan"],
        "gpt": {
            "model_dim": 32, "heads": 4, "layers": 2,
            "max_mel_tokens": 48, "max_text_tokens": 48,
            "number_text_tokens": 24, "number_mel_codes": 16,
            "start_mel_token": 14, "stop_mel_token": 15,
            "start_text_token": 22, "stop_text_token": 23,
            "use_mel_codes_as_input": true,
            "mel_length_compression": 1024,
            "condition_type": "something_else",
            "condition_module": fixture_config["gpt"]["condition_module"]
        }
    }))
    .unwrap_err();
    assert!(refused.to_string().contains("condition_type"), "{refused}");

    // The invalid default input_layer (a KeyError in the reference
    // CONV_LAYERS lookup) is refused.
    let mut bad_condition = fixture_config["gpt"]["condition_module"].clone();
    bad_condition["input_layer"] = serde_json::json!("conv2d");
    let refused = super::ConformerArgs::from_json(&bad_condition).unwrap_err();
    assert!(refused.to_string().contains("input_layer"), "{refused}");
}

#[test]
fn generate_refuses_an_empty_mel() {
    let mut model = fixture_model();
    let error = model
        .generate(&[], &[5, 6, 7], &GenerateParams::default(), 0)
        .unwrap_err();
    assert!(error.to_string().contains("empty reference mel"), "{error}");
}
